      "rationale": {
        "observation": "An automated change caused a core site isolation and emergency-call routing failure; logs will show the closed-loop optimiser's decision and the skipped sandbox stage.",
        "rule": "Preserving logs and evidence supports incident investigation and any regulatory response.",
        "inference": "Preserving logs now reduces risk of losing evidence of the failed change and emergency-call impact."
      },
      "evidence": [
        {
          "chunk_id": "AU-ACMA-OPTUS-2026#0000",
          "quote": "The proceedings follow earlier enforcement action taken by the ACMA arising from the Optus November 2023 outage. Singtel Optus subsidiaries, including Optus Mobile, paid more than $12 million in infringement notice penalties imposed by the ACMA for breaches relating to emergency calls."
        }
